}

export default SingleProduct;

SingleProduct.getInitialProps = async (ctx) => {

    const { query } = ctx;
    return WooCommerce.get(`products/${query.id}`)
        .then((response) => {
            console.log(response.data);
        })
        .catch((error) => {
            console.log(error.response.data);
        });
}
